-- SQLite fallback schema (only used when FWZ_DB=sqlite). The real target is schema.sql (MySQL).
DROP TABLE IF EXISTS donations;
DROP TABLE IF EXISTS waste_log;
DROP TABLE IF EXISTS actions;
DROP TABLE IF EXISTS sales;
DROP TABLE IF EXISTS batches;
DROP TABLE IF EXISTS partners;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS categories;
DROP TABLE IF EXISTS users;

CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, donatable INTEGER NOT NULL DEFAULT 1);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category_id INTEGER NOT NULL REFERENCES categories(id), unit TEXT NOT NULL DEFAULT 'pc', unit_cost REAL NOT NULL, unit_price REAL NOT NULL, kg_per_unit REAL NOT NULL DEFAULT 0.5, shelf_life_days INTEGER NOT NULL DEFAULT 7, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE batches (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), batch_code TEXT NOT NULL, qty_received INTEGER NOT NULL, qty_remaining INTEGER NOT NULL, received_on TEXT NOT NULL, expires_on TEXT NOT NULL, discount_pct REAL NOT NULL DEFAULT 0);
CREATE TABLE sales (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), batch_id INTEGER REFERENCES batches(id) ON DELETE SET NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, discount_pct REAL NOT NULL DEFAULT 0, sold_on TEXT NOT NULL);
CREATE TABLE partners (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'charity', area TEXT, phone TEXT);
CREATE TABLE actions (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id INTEGER NOT NULL REFERENCES batches(id) ON DELETE CASCADE, action_type TEXT NOT NULL, discount_pct REAL NOT NULL DEFAULT 0, qty_affected INTEGER NOT NULL DEFAULT 0, urgency TEXT NOT NULL DEFAULT 'medium', rationale TEXT, est_value REAL NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT);
CREATE TABLE donations (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), batch_id INTEGER REFERENCES batches(id) ON DELETE SET NULL, partner_id INTEGER NOT NULL REFERENCES partners(id), quantity INTEGER NOT NULL, kg REAL NOT NULL, meals INTEGER NOT NULL, donated_on TEXT NOT NULL);
CREATE TABLE waste_log (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), batch_id INTEGER REFERENCES batches(id) ON DELETE SET NULL, quantity INTEGER NOT NULL, kg REAL NOT NULL, cost_loss REAL NOT NULL, reason TEXT NOT NULL DEFAULT 'expired', logged_on TEXT NOT NULL);
